export const PRESETS: readonly PerformancePresetFamily[] = [
    SqookyDefault,
    SqookyTesting,
    BootMaxFps,
    KaizuMinSpec,
    OptilockFps,
    OptilockMax,
];

export const DEFAULT_PRESET_ID = 'sqooky-default';

export function getFamily(id: string | null | undefined): PerformancePresetFamily {
    return PRESETS.find((p) => p.id === id) ?? PRESETS.find((p) => p.id === DEFAULT_PRESET_ID)!;
}

/** Resolve a preset at one release, flattened for the patcher.
 *
 *  An unknown `version` falls back to the newest release rather than
 *  throwing: it is what a gameinfo.gi marker written by an older Grimoire
 *  carries once that release ages out of the bundled window, and the caller
 *  detects that case by comparing the marker itself (see isCurrentDefinition
 *  in performanceConfig.ts), not by trusting this lookup. */
export function getPreset(
    id: string | null | undefined,
    version?: string | null
): PerformancePreset {
    const family = getFamily(id);
    const release =
        family.releases.find((r) => r.version === version) ?? family.releases[0];
    return {
        id: family.id,
        name: family.name,
        version: release.version,
        tier: family.tier,
        author: family.author,
        ...(family.unstable ? { unstable: true } : {}),
        upstream: {
            ...family.upstream,
            ref: release.ref,
            refKind: release.refKind,
            commit: release.commit,
        },
        sectionOps: release.sectionOps,
        convars: release.convars,
        optIn: release.optIn,
    };
}

/** True when `version` names a release this build actually bundles. */
export function hasVersion(id: string, version: string | null | undefined): boolean {
    return getFamily(id).releases.some((r) => r.version === version);
}
